target.css:
:root {
  --ink: #272237;
  --muted: #766f85;
  --paper: #fffdf8;
  --lilac: #eeeafb;
  --lavender: #d8cefa;
  --plum: #6246a3;
  --plum-dark: #403064;
  --mint: #d9f0de;
  --mint-ink: #237147;
  --line: #ded8e8;
}

* {
  box-sizing: border-box;
}

.proof-card {
  width: 500px;
  padding: 16px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line);
}

.title-block {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.eyebrow {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.07em;
  line-height: 1.2;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-size: 22px;
  font-weight: 750;
  letter-spacing: -0.04em;
  line-height: 1;
}

.status {
  padding: 5px 9px;
  color: var(--mint-ink);
  background: var(--mint);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 750;
  line-height: 1;
}

.proof-layout {
  display: grid;
  grid-template-columns: 184px 1fr;
  gap: 12px;
  padding: 12px 0;
}

.glyph-panel {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  height: 132px;
  margin: 0;
  padding: 9px 12px 8px;
  background: var(--lilac);
  border: 1px solid var(--lavender);
  border-radius: 12px;
}

.glyph {
  color: var(--plum-dark);
  font-size: 86px;
  font-weight: 500;
  line-height: 0.88;
}

figcaption {
  color: var(--plum);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  line-height: 1;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
}

.metric {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 0;
  padding: 8px 10px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 10px;
}

.metric span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.1;
}

.metric strong {
  margin-top: 3px;
  color: var(--plum-dark);
  font-size: 20px;
  font-weight: 750;
  line-height: 0.95;
}

.metric small {
  margin-top: 3px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1;
}

.metric.accent {
  grid-column: span 2;
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  background: var(--plum-dark);
  border-color: var(--plum-dark);
}

.metric.accent span,
.metric.accent small {
  color: var(--lavender);
}

.metric.accent strong {
  margin: 0 0 0 auto;
  padding-right: 8px;
  color: var(--paper);
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 11px;
  border-top: 1px solid var(--line);
}

.card-footer p {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 650;
  line-height: 1;
}

.dot {
  width: 7px;
  height: 7px;
  background: var(--plum);
  border-radius: 50%;
}

.footer-actions {
  display: flex;
  gap: 6px;
}

button {
  padding: 7px 10px;
  border-radius: 8px;
  font-size: 11px;
  font-weight: 750;
  line-height: 1;
}

.secondary {
  color: var(--plum);
  background: var(--paper);
  border: 1px solid var(--lavender);
}

.primary {
  color: var(--paper);
  background: var(--plum);
  border: 1px solid var(--plum);
}

